template <typename I1, typename I2, typename O, typename Compare>
O merge_impl(I1 f1, I1 l1, I2 f2, I2 l2, O result, Compare comp) {
    while (f1 != l1 && f2 != l2) {
        if (comp(*f2, *f1)) { // *f2 precedes *f1
            *result++ = *f2++;
        } else {
            *result++ = *f1++;
        }
    }
    // Exhaust remaining elements (optimized via std::copy)
    if (f1 != l1) {
        result = std::copy(f1, l1, result);
    } else {
        result = std::copy(f2, l2, result);
    }
    return result;
}
